// One-bit Synchronous Finite State Machine, used to recognize a byte
// received on a serial line (start bit, 8 data bits, stop bit).
module FSM (
    input clk,
    input reset,
    input in,
    output reg done
);
    reg [2:0] state;
    reg [7:0] data;
    reg [2:0] bit_counter;
    always @(posedge clk) begin
        if (reset) begin
            state <= 3'b000;
            done <= 1'b0;
            bit_counter <= 3'b000;
        end else begin
            case (state)
                3'b000: begin // Wait for start bit
                    if (in == 1'b0) begin
                        state <= 3'b001;
                        bit_counter <= 3'b001;
                    end
                end
                3'b001: begin // Read data bits
                    data <= {in, data[7:1]};
                    bit_counter <= bit_counter + 1;
                    if (bit_counter == 3'b100) begin
                        state <= 3'b010;
                    end
                end
                3'b010: begin // Wait for stop bit
                    if (in == 1'b1) begin
                        state <= 3'b000;
                        done <= 1'b1;
                    end
                end
            endcase
        end
    end
endmodule

