// One-shot pulse generator, triggered by a 0->1 transition on the
// "pulse" input. Active-high, synchronous reset.
module PulseGenerator(
    input clk, reset, pulse,
    output reg pulse_once
);
    reg pulse_d1;
    always @(posedge clk) begin
        if (reset) begin
            pulse_d1 <= 1'b0;
            pulse_once <= 1'b0;
        end else begin
            pulse_d1 <= pulse;
            pulse_once <= pulse & ~pulse_d1;
        end
    end
endmodule

